<?php
declare(strict_types=1);
require_once __DIR__.'/stock-matrix.php';require_once __DIR__.'/size-versions.php';
function size_measurements(string $text):?array {
 $t=mb_strtolower(str_replace(',','.',$text),'UTF-8');$h=null;$w=null;
 if(preg_match('/(?<![\d.])(?:cao\s*)?([12])\s*m(?:ét)?\s*(\d{1,2})/u',$t,$m))$h=(int)$m[1]*100+(int)str_pad($m[2],2,'0',STR_PAD_RIGHT);
 elseif(preg_match('/\b([12]\.\d{1,2})\s*m?/u',$t,$m))$h=(float)$m[1]*100;
 elseif(preg_match('/(?:cao\s*|\b)(1\d{2}|2[01]\d)\s*(?:cm)?/u',$t,$m))$h=(float)$m[1];
 if(preg_match('/(?:nặng|nang)\s*(\d{2,3}(?:\.\d+)?)/u',$t,$m)||preg_match('/(\d{2,3}(?:\.\d+)?)\s*(?:kg|kí|ki|ký|k)(?![\p{L}])/u',$t,$m))$w=(float)$m[1];
 elseif(preg_match('/^\s*(?:1\d{2}|2[01]\d|[12]\.\d{1,2})\s*[\/; -]\s*(\d{2,3}(?:\.\d+)?)\s*$/u',$t,$m))$w=(float)$m[1];
 return $h!==null&&$w!==null&&$h>=120&&$h<=220&&$w>=25&&$w<=250?['height'=>round($h),'weight'=>$w]:null;
}
function size_wilson(int $bad,int $n):array {if(!$n)return [0,1];$z=1.96;$p=$bad/$n;$d=1+$z*$z/$n;$c=($p+$z*$z/(2*$n))/$d;$e=$z*sqrt($p*(1-$p)/$n+$z*$z/(4*$n*$n))/$d;return [$c-$e,$c+$e];}
function size_fit_reason(string $reason):bool {$upper=mb_strtoupper($reason,'UTF-8');return (bool)preg_match('/CHẬT|RỘNG|NGẮN|DÀI|LỎNG|KHÔNG VỪA|K VỪA|\\bSIZE\\b/u',$upper)||(bool)preg_match('/\\b(?:RONG|NGAN|DAI|KHONG VUA|K VUA)\\b|\\bCHAT\\s+(?:BUNG|NGUC|TAY|ONG)\\b/u',report_fold($reason));}
function size_analyze(array $rows,array $cases):array {
 $byTracking=[];foreach($cases as $c)$byTracking[$c['tracking']]=$c;$products=[];$bins=[];$seen=[];$versionCounts=[];
 foreach(stock_group_rows($rows) as $row){if(!$row['created'])continue;$tracking=stock_tracking($row['tracking']);$identity=$tracking!==''?$tracking:$row['sheetId'].'|'.$row['row'];if(isset($seen[$identity]))continue;$seen[$identity]=true;$case=$byTracking[$tracking]??null;$body=size_measurements($row['measurements']??'');$delivered=(bool)preg_match('/^(?:GIAO THANH CONG|DA GIAO|KHACH DA NHAN|THANH CONG|DELIVERED)(?:$|[ .,!])/u',report_fold($row['status']??''));$bySku=[];
 foreach($row['items'] as $i){$key=$i['sku'].'|'.$i['size'];$returned=$case&&!$case['error']?min($i['qty'],(int)($case['items'][$key]??0)):0;$accepted=($delivered||($case&&$case['state']==='received'&&!$case['error']))?max(0,$i['qty']-$returned):0;$sku=$i['sku'];$products[$sku]??=['sku'=>$sku,'sentOrders'=>0,'returnOrders'=>0,'sentQty'=>0,'returnQty'=>0,'acceptedQty'=>0,'measured'=>0,'fitReturns'=>0,'unresolved'=>0];$p=&$products[$sku];$p['sentQty']+=$i['qty'];$p['returnQty']+=$returned;$p['acceptedQty']+=$accepted;$bySku[$sku]=($bySku[$sku]??false)||$returned>0;$fit=$returned>0&&size_fit_reason($case['reason']??'');if($fit)$p['fitReturns']+=$returned;
 if($body){$p['measured']+=$i['qty'];$height=(int)(floor($body['height']/5)*5);$weight=(int)(floor($body['weight']/5)*5);$bkey=$sku.'|'.$height.'|'.$weight;$bins[$bkey]??=['sku'=>$sku,'height'=>$height,'weight'=>$weight,'sizes'=>[]];$bins[$bkey]['sizes'][$i['size'].' · '.(isset($row['sizeCharts'][$sku])?'#'.$row['sizeCharts'][$sku]['id'].' '.$row['sizeCharts'][$sku]['name']:'Chưa gán bảng size')]??=['accepted'=>0,'returned'=>0];$bins[$bkey]['sizes'][$i['size']]['accepted']+=($accepted>0&&$returned===0)?1:0;$bins[$bkey]['sizes'][$i['size']]['returned']+=$fit?1:0;}
 unset($p);}
 foreach($bySku as $sku=>$hasReturn){$versionId=$row['sizeCharts'][$sku]['id']??0;$versionCounts[$sku][$versionId]??=['sent'=>0,'returned'=>0];$versionCounts[$sku][$versionId]['sent']++;if($hasReturn)$versionCounts[$sku][$versionId]['returned']++;$products[$sku]['sentOrders']++;if($hasReturn)$products[$sku]['returnOrders']++;if($case&&$case['error'])$products[$sku]['unresolved']++;}
 }
 foreach($products as &$p){$p['returnRate']=$p['sentOrders']?round(100*$p['returnOrders']/$p['sentOrders'],1):0;$p['acceptedRate']=$p['sentQty']?round(100*$p['acceptedQty']/$p['sentQty'],1):0;$p['alert']=$p['returnRate']>35;foreach($versionCounts[$p['sku']]??[] as $v)if($v['sent']&&100*$v['returned']/$v['sent']>35)$p['alert']=true;}unset($p);
 $proposals=[];foreach($bins as $bin){if(empty($products[$bin['sku']]['alert']))continue;foreach($bin['sizes'] as $oldSize=>$old){$oldN=$old['accepted']+$old['returned'];if($oldN<20)continue;[$oldLow]=size_wilson($old['returned'],$oldN);$best=null;foreach($bin['sizes'] as $newSize=>$new){$n=$new['accepted']+$new['returned'];if($newSize===$oldSize||$n<20||$new['accepted']<10)continue;[, $upper]=size_wilson($new['returned'],$n);$rate=$new['returned']/$n;if($upper<$oldLow&&$old['returned']/$oldN-$rate>=.1&&(!$best||$rate<$best['rate']))$best=['size'=>$newSize,'n'=>$n,'rate'=>$rate];}if($best)$proposals[]=['sku'=>$bin['sku'],'height'=>$bin['height'].'–'.($bin['height']+4).' cm','weight'=>$bin['weight'].'–<'.($bin['weight']+5).' kg','from'=>$oldSize,'to'=>$best['size'],'before'=>round(100*$old['returned']/$oldN,1),'after'=>round(100*$best['rate'],1),'samples'=>$oldN.' / '.$best['n']];}}
 usort($products,static fn($a,$b)=>$b['alert']<=>$a['alert']?:$b['returnRate']<=>$a['returnRate']);return ['products'=>array_values($products),'cohorts'=>array_values($bins),'proposals'=>$proposals,'alerts'=>count(array_filter($products,static fn($p)=>$p['alert']))];
}
function size_insights(PDO $db,array $input):array {
 team_require_owner();wb_schema($db);size_versions_schema($db);$from=(string)($input['from']??'');$to=(string)($input['to']??'');foreach([$from,$to] as $date)if($date!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$date))throw new RuntimeException('Ngày không hợp lệ.',400);if($from!==''&&$to!==''&&$from>$to)throw new RuntimeException('Kiểm tra khoảng ngày.',400);$db->exec('CREATE TABLE IF NOT EXISTS size_insight_cache(cache_key TEXT PRIMARY KEY,result TEXT NOT NULL,created_at INTEGER NOT NULL)');$version=$db->query('SELECT version FROM staff_workbook WHERE id=1')->fetchColumn();$versions=$db->query('SELECT * FROM size_chart_versions ORDER BY sku,date_from')->fetchAll();$key=hash('sha256','v4|'.json_encode($versions).$version.'|'.$from.'|'.$to);$q=$db->prepare('SELECT result FROM size_insight_cache WHERE cache_key=? AND created_at>?');$q->execute([$key,time()-120]);if($json=$q->fetchColumn())return json_decode($json,true);$catalog=board_catalog($db);$board=board_rows($db,$catalog);$flow=stock_flow($db,$board['rows']);$assigned=size_assign_versions($db,$board['rows'],$versions);$rows=array_values(array_filter($assigned,static fn($r)=>($from===''||$r['date']>=$from)&&($to===''||$r['date']<=$to)));$result=size_analyze($rows,$flow['cases']);$result['version']=$board['version'];$result['versions']=$versions;$result['versionStats']=size_version_results($rows,$flow['cases'],$versions);$db->prepare('INSERT OR REPLACE INTO size_insight_cache VALUES(?,?,?)')->execute([$key,json_encode($result,JSON_UNESCAPED_UNICODE),time()]);$db->exec('DELETE FROM size_insight_cache WHERE created_at<'.(time()-600));return $result;
}
